package main

import "fmt"

func main() {
    fmt.Println("Hello")
}

nums := []int{1, 2, 3}
for _, num := range nums {
    fmt.Println(num)
}

type Order struct {
    Name string
    Value int
}

result, err := someFunction()
if err != nil {
    log.Fatal(err)
}

ch := make(chan int)
 go func() {
    ch <- 42
 }()
<-ch

var ptr *int
if ptr != nil {
    fmt.Println(*ptr)
}

type Reader interface {
    Read(p []byte) (n int, err error)
}

data := map[string]interface{}{
    "key": "value",
}

func add(a, b int) int {
    return a + b
}

