    println!("{}", item);
}

struct Order {
    name: String,
    value: i32,
}

match result {
    Ok(val) => println!("{}", val),
    Err(e) => println!("Error: {}", e),
}

let filtered: Vec<i32> = nums.iter()
    .filter(|&&x| x > 0)
    .cloned()
    .collect();

let handle = std::thread::spawn(|| {
    println!("From thread");
});
handle.join().unwrap();

match option {
    Some(x) => x,
    None => 0,
}

trait Speak {
    fn speak(&self);
}

impl Speak for Dog {
    fn speak(&self) {}
}

let result = (1..100)
    .filter(|x| x % 2 == 0)
    .map(|x| x * 3)
    .collect::<Vec<_>>();

