body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 20px;
}

.container {
    display: flex;
    justify-content: center;
    align-items: center;
}

#header {
    background-color: #333;
    color: white;
    padding: 10px;
}

@media (max-width: 768px) {
    .container {
        flex-direction: column;
    }
}

